WITH scored AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY location ORDER BY budget DESC, id) AS row_seq, FIRST_VALUE(budget, TRUE) OVER (PARTITION BY dept_name ORDER BY budget, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_budget FROM departments) SELECT location, SUM(CASE WHEN dept_name = 'HR' THEN first_known_budget ELSE 0 END) AS hr_first_known_budget, COUNT(CASE WHEN location = 'Chiang Mai' THEN 1 END) AS chiang_mai_count, GROUPING(location) AS gid FROM scored GROUP BY ROLLUP (location) HAVING hr_first_known_budget < 1000000;
